  {
    "alert_id": "ALERT_001",
    "title": "TDF toxicity: low phosphate and bone pain",
    "message": "Guidelines list TDF as causing Fanconi syndrome, decreased bone mineral density, and lower back pain with bone aches; management is LFTs and RFTs, substituting TDF with ABC if GFR <60 or deranged. Patient on TDF for 6 years presents with lower back pain and heavy thighs worsening over 4 months, plus low serum phosphate 0.78 mmol/L and trace proteinuria. These findings are consistent with proximal tubulopathy (Fanconi syndrome) and bone mineral density loss from TDF. Creatinine is 112 umol/L, which may appear normal but does not exclude tubular dysfunction. Occupational strain from truck driving is an alternative explanation for back pain, but the concurrent hypophosphataemia and proteinuria strengthen drug attribution. eGFR has not been calculated.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Calculate eGFR and perform urinalysis for phosphate and glucose. If deranged, substitute TDF with ABC per guidelines. Evaluate bone mineral density.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 24, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p24_c1"}
    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "TDF monitoring gap: annual creatinine and eGFR",
    "message": "Guidelines require serum creatinine and eGFR monitoring every 12 months for experienced patients on TDF. Patient has been on TDF for 6 years, but no eGFR is documented. Today's creatinine of 112 umol/L is at the upper end of normal and trace proteinuria is present. Without eGFR calculation, renal function cannot be adequately assessed, especially given concurrent hypophosphataemia suggesting possible tubular dysfunction. The clinician's plan does not include renal monitoring.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate eGFR from today's creatinine. Schedule annual serum creatinine and eGFR monitoring as per TDF monitoring guidelines.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Uncontrolled BP and NSAID risk with TDF",
    "message": "Guidelines define persistently high resting BP as >140/90 mmHg requiring management. Patient's BP is 146/94, attributed partly to missed amlodipine doses. The plan only refills amlodipine without intensifying antihypertensive therapy. Additionally, the clinician recommends PRN ibuprofen, an NSAID that can worsen hypertension and cause renal injury. Combined with TDF, which is nephrotoxic, and existing trace proteinuria with low phosphate, NSAID use compounds renal risk. The plan lacks renal-sparing analgesic alternatives.",
    "issue_type": "compounding_risk",
    "severity": "high",
    "recommended_action": "Confirm BP >140/90 with repeat measurement after 5 minutes seated. Intensify antihypertensive management. Consider acetaminophen instead of ibuprofen for back pain to reduce renal risk.",
    "citations": [
      {"page_number": 40, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__p40_c2"},
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  },
  {
    "alert_id": "ALERT_004",
    "title": "EFV regimen not guideline-preferred first-line",
    "message": "Guidelines recommend DTG-based regimens (TDF+3TC+DTG) as preferred first-line for adults, with EFV400 as an alternative when DTG is contraindicated. Patient remains on EFV-based ART for 6 years. EFV is associated with CNS toxicity, hepatotoxicity, and gynecomastia. While the patient is virologically suppressed, no contraindication to DTG is documented, and no reason for continuing EFV over DTG is noted. The plan does not address potential regimen optimization.",
    "issue_type": "guideline_deviation",
    "severity": "low",
    "recommended_action": "Assess for any contraindication to DTG. If none, consider transitioning to TDF+3TC+DTG per preferred first-line guidelines.",
